using System;using System.Linq;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class TestGroveInteractions {
 public static string Main(){if(!Application.isPlaying)throw new Exception("Play only");var root=GameObject.Find("EnvironmentExpansion/DrownedGrove");var p=GameObject.Find("Player");var body=p.GetComponent<Rigidbody2D>();var interaction=p.GetComponent<PlayerInteractionController>();var inv=p.GetComponent<InventoryController>();var log=new List<string>();
 foreach(var chest in root.GetComponentsInChildren<LootChest>()){Vector2 spot=(Vector2)chest.transform.position+Vector2.down*.8f;body.position=spot;p.transform.position=spot;Physics2D.SyncTransforms();int before=Enumerable.Range(0,25).Sum(i=>inv.GetSlot(i).Quantity);chest.Use(interaction);int after=Enumerable.Range(0,25).Sum(i=>inv.GetSlot(i).Quantity);log.Add((chest.Opened&&after>before?"PASS":"FAIL")+" "+chest.name+" opened="+chest.Opened+" lootAdded="+(after-before)+" animationPlaying="+(chest.openingAnimation&&chest.openingAnimation.IsPlaying));}
 foreach(var node in root.GetComponentsInChildren<ResourceNode>()){var pos=(Vector2)node.transform.position+Vector2.down*.9f;body.position=pos;p.transform.position=pos;Physics2D.SyncTransforms();if(node.type==ResourceType.Scrap)node.Use(interaction);else node.Hit(node.maxHealth,interaction);log.Add((node.Depleted?"PASS":"FAIL")+" "+node.name+" gameplay API depleted="+node.Depleted);}
 var e=root.GetComponent<AshenFrontierEncounterController>();body.position=new Vector2(-23,19.5f);p.transform.position=body.position;Physics2D.SyncTransforms();e.EvaluateEncounters();var slot=e.rogueSlots.First(s=>s.isCaptain);if(!slot.instance){log.Add("FAIL boss not spawned");}else{var hp=slot.instance.GetComponent<EnemyHealth>();var before=hp.CurrentHealth;hp.TakeDamage(10,p.transform.position,0);log.Add((hp.CurrentHealth==before-10?"PASS":"FAIL")+" boss receives damage "+before+" -> "+hp.CurrentHealth);hp.TakeDamage(999,p.transform.position,0);int drops=UnityEngine.Object.FindObjectsByType<ResourcePickup>(FindObjectsInactive.Exclude).Count(r=>r.name.StartsWith("MarshWardenSpoils_"));log.Add((drops>0&&slot.defeated?"PASS":"FAIL")+" boss defeat flag="+slot.defeated+" reward pickups="+drops);}
 log.Add("Global population="+e.existingSpawner.TotalActiveCount+" local="+e.LocalActiveCount+" local cap="+e.maxConcurrentLocalEnemies);
 File.WriteAllLines("Design/DrownedGrove/InteractionTests.txt",log);return string.Join("\n",log);
 }
}
